const data = $input.first().json;
const rows = data.byLocationAndStatus || [];
const specialties = data.bySpecialty || [];

// Conteos por sede y por estado, a partir de la misma lista: el backend agrupa y aqui solo
// se reorganiza para redactar, sin recalcular nada.
const bySite = {};
const byStatus = {};
for (const row of rows) {
  bySite[row.locationName] = (bySite[row.locationName] || 0) + row.total;
  byStatus[row.status] = (byStatus[row.status] || 0) + row.total;
}

const line = (label, value) => `<li><b>${label}:</b> ${value}</li>`;
const siteLines = Object.keys(bySite).sort().map(k => line(k, bySite[k])).join("");
const statusLines = ["APPROVED", "COMPLETED", "NO_SHOW", "CANCELLED", "REQUESTED", "REJECTED"]
  .filter(code => byStatus[code])
  .map(code => line(code, byStatus[code])).join("");
const specialtyLines = specialties.map(s => line(s.specialtyName, s.total)).join("");

const html = `<p>Resumen operativo del <b>${data.date}</b>.</p>`
  + `<p>Total de citas del dia: <b>${data.total}</b></p>`
  + (siteLines ? `<p>Por sede:</p><ul>${siteLines}</ul>` : "")
  + (statusLines ? `<p>Por estado:</p><ul>${statusLines}</ul>` : "")
  + (specialtyLines ? `<p>Por especialidad:</p><ul>${specialtyLines}</ul>` : "")
  + (data.total === 0 ? "<p>No hubo citas programadas para este dia.</p>" : "")
  + "<p>Entorno de laboratorio con datos sinteticos.</p>";

return [{ json: { date: data.date, total: data.total, html } }];
